def makeDict(versionString, signalStringList, bkgStringList):
    signalDict = {}
    bkgDict = {}
    for sample, fileString in DATASETS[versionString].items():
        for string in signalStringList:
            if string in sample:
                signalDict[sample] = fileString
        for string in bkgStringList:
            if string in sample:
                bkgDict[sample] = fileString
    return signalDict, bkgDict
